// Deep, hand-authored content for a sub-topic's detailed page (the center modal).
// Only sub-topics with an entry here open the deep modal; others fall back to
// the side sheet. This is the gold-standard template - author more to match.

export interface PostVariation {
  kind: string; // "X thread" | "Belief-shift (one-liner)" | "LinkedIn"
  hook: string;
  body: string; // full copy-ready text
}

export interface DeepContent {
  id: string; // matches SubNode.id in roadmap.json
  title: string;
  kindLabel: string; // Anti-pattern / Mental model / ...
  // 1. What it is
  definition: string;
  // 2. Technical explanation
  technical: string;
  // 3. The metaphor
  metaphor: { label: string; body: string };
  // 4. Real-world example (where + why)
  example: {
    product: string;
    scenario: string; // the concrete situation
    why: string; // why it matters / what it costs
  };
  // 5. what the annotated interactive demo should teach (the demo is a custom component)
  demoCaption: string;
  // 6. ready-to-post, 3 variations
  posts: PostVariation[];
}

