export function getDeep(id: string | undefined): DeepContent | undefined {
  return id ? DEEP[id] : undefined;
}

// Accent tone for the kind pill in the modal header (kindLabel is dynamic now).
export function kindTone(kindLabel: string): { fg: string; tint: string } {
  switch (kindLabel) {
    case 'Mental model': return { fg: 'var(--model)', tint: 'var(--model-tint)' };
    case 'Pattern': return { fg: 'var(--pattern)', tint: 'var(--pattern-tint)' };
    case 'Anti-pattern': return { fg: 'var(--anti)', tint: 'var(--anti-tint)' };
    case 'Invisible problem': return { fg: 'var(--invisible)', tint: 'var(--invisible-tint)' };
    default: return { fg: 'var(--ink-2)', tint: 'var(--surface-2)' };
  }
}

// Which reusable demo template a sub-topic maps to.
// IMPORTANT: a demo is only shown when it genuinely fits the concept. Mapping
// by the id's kind segment alone mis-matches (e.g. an anti-pattern about missing
// states does not fit a confirm-order demo), and a demo that contradicts its own
// caption actively misteaches. So template demos are opt-in per id: only ids
// listed in DEMO_TEMPLATE get an Interactive tab. Everything else is text-only
// until a matching demo is authored. The bespoke pilot is registered separately.
export type DemoTemplate = 'confirm-order' | 'state-machine' | 'loop-close';

export const DEMO_TEMPLATE: Record<string, DemoTemplate> = {
  // hand-verified matches (concept genuinely fits the template)
  'systems-state-design-anti-2': 'state-machine',   // the dead spinner (loading with no timeout branch)
  'systems-state-design-inv-6': 'state-machine',     // state the backend has but the frontend collapses
  'task-based-saas-anti-3': 'loop-close',            // terminal success screen / dead end
  'task-based-saas-inv-3': 'loop-close',             // dead ends from missing next-state routing
};

export function demoTemplateFor(id: string): DemoTemplate | null {
  return DEMO_TEMPLATE[id] ?? null;
}
